func GetCurrentBranch(ctx context.Context) (string, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return "", fmt.Errorf("failed to open git repository: %w", err)
	}
	defer repo.Close()

	head, err := repo.Head()
	if err != nil {
